import React, { useMemo, useState } from "react";

/**
 * ComprasPanel.jsx
 * Panel de demostración del módulo Compras de Inventi Pro.
 * Incluye las seis vistas visuales de referencia: compra rápida, nueva orden,
 * formulario de orden, detalle de compra/documento, vista previa documental y proveedores.
 * Los datos son de demostración y permanecen en memoria; no se conecta a una API.
 */

